    rmsRelTip: '相对厚度误差（膜层厚度 d 的百分比），加到 σ 绝对上。确切含义取决于分布选择器；对高斯分布约 68% 的膜层保持在 ±此值内。',
    rmsReNTip: '折射率 n 实部的误差。确切含义取决于分布选择器；对高斯分布约 68% 的膜层保持在 ±此值内。',
